public List<String> fullJustify(String[] words, int maxWidth) {
    List<String> result = new ArrayList<>();
    int i = 0, n = words.length;
    while (i < n) {
        int j = i, lineLen = 0;
        while (j < n && lineLen + (j - i) + words[j].length() <= maxWidth) {
            lineLen += words[j].length();
            j++;
        }
        int numWords = j - i;
        StringBuilder sb = new StringBuilder();
        if (j == n || numWords == 1) {
            for (int k = i; k < j; k++) {
                if (k > i) sb.append(' ');
                sb.append(words[k]);
            }
            while (sb.length() < maxWidth) sb.append(' ');
        } else {
            int spaces = maxWidth - lineLen;
            int gaps = numWords - 1;
            int each = spaces / gaps;
            int extra = spaces % gaps;
            for (int k = i; k < j; k++) {
                sb.append(words[k]);
                if (k < j - 1) {
                    int add = each + ((k - i) < extra ? 1 : 0);
                    for (int s = 0; s < add; s++) sb.append(' ');
                }
            }
        }
        result.add(sb.toString());
        i = j;
    }
    return result;
}

