public List<String> fullJustify(String[] words, int maxWidth) {
    List<String> result = new ArrayList<>();
    List<String> line = new ArrayList<>();
    int lineLen = 0;
    for (String word : words) {
        if (lineLen + line.size() + word.length() > maxWidth) {
            int spaces = maxWidth - lineLen;
            StringBuilder sb = new StringBuilder();
            if (line.size() == 1) {
                sb.append(line.get(0));
                for (int s = 0; s < spaces; s++) sb.append(' ');
            } else {
                int gaps = line.size() - 1;
                int each = spaces / gaps, extra = spaces % gaps;
                for (int k = 0; k < line.size(); k++) {
                    sb.append(line.get(k));
                    if (k < gaps) {
                        int add = each + (k < extra ? 1 : 0);
                        for (int s = 0; s < add; s++) sb.append(' ');
                    }
                }
            }
            result.add(sb.toString());
            line.clear();
            lineLen = 0;
        }
        line.add(word);
        lineLen += word.length();
    }
    StringBuilder last = new StringBuilder();
    for (int k = 0; k < line.size(); k++) {
        if (k > 0) last.append(' ');
        last.append(line.get(k));
    }
    while (last.length() < maxWidth) last.append(' ');
    result.add(last.toString());
    return result;
}

